Action: run_sql({'query': "WITH est_cuisine AS (\n  SELECT DISTINCT \n    e.gmap_id,\n    e.name,\n    e.avg_rating,\n    e.num_of_reviews,\n    e.slchd_establishment_key,\n    CASE \n      WHEN c.category ILIKE '%thai%' THEN 'Thai'\n      WHEN c.category ILIKE '%korean%' AND c.category != 'Korean grocery store' THEN 'Korean'\n    END AS cuisine\n  FROM establishments e\n  JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\n  JOIN category c ON ec.category_id = c.category_id\n  WHERE c.category ILIKE '%thai%' OR (c.category ILIKE '%korean%' AND c.category != 'Korean grocery store')\n),\ncuisine_ratings AS (\n  SELECT \n    cuisine,\n    COUNT(DISTINCT gmap_id) as total_establishments,\n    COUNT(DISTINCT slchd_establishment_key) as matched_establishments,\n    AVG(avg_rating) as mean_avg_rating,\n    MEDIAN(avg_rating) as median_avg_rating,\n    SUM(num_of_reviews) as total_reviews\n  FROM est_cuisine\n  GROUP BY cuisine\n),\nviolations_summary AS (\n  SELECT \n    ec.cuisine,\n    COUNT(DISTINCT i.inspection_id) as total_inspections,\n    COUNT(v.violation_id) as total_violations,\n    SUM(CASE WHEN vc.critical THEN 1 ELSE 0 END) as total_critical_violations,\n    SUM(CASE WHEN NOT vc.critical THEN 1 ELSE 0 END) as total_noncritical_violations\n  FROM est_cuisine ec\n  JOIN inspections i ON ec.slchd_establishment_key = i.slchd_establishment_key\n  LEFT JOIN violations v ON i.inspection_id = v.inspection_id\n  LEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\n  GROUP BY ec.cuisine\n)\nSELECT \n  cr.cuisine,\n  cr.total_establishments,\n  cr.matched_establishments,\n  ROUND(cr.mean_avg_rating, 3) as mean_avg_rating,\n  ROUND(cr.median_avg_rating, 3) as median_avg_rating,\n  vs.total_inspections,\n  vs.total_violations,\n  vs.total_critical_violations,\n  vs.total_noncritical_violations,\n  ROUND(CAST(vs.total_violations AS DOUBLE) / NULLIF(vs.total_inspections, 0), 2) as violations_per_inspection,\n  ROUND(CAST(vs.total_violations AS DOUBLE) / NULLIF(cr.matched_establishments, 0), 2) as violations_per_matched_est,\n  ROUND(CAST(vs.total_critical_violations AS DOUBLE) / NULLIF(vs.total_inspections, 0), 2) as critical_per_inspection\nFROM cuisine_ratings cr\nLEFT JOIN violations_summary vs ON cr.cuisine = vs.cuisine;"})

