Action: run_sql({'query': "WITH base AS (\n  SELECT DISTINCT\n    e.gmap_id,\n    e.name,\n    e.avg_rating,\n    e.num_of_reviews,\n    e.slchd_establishment_key,\n    MAX(CASE WHEN c.category ILIKE '%thai%' OR e.name ILIKE '%thai%' THEN 1 ELSE 0 END) as is_thai,\n    MAX(CASE WHEN (c.category ILIKE '%korean%' OR e.name ILIKE '%korean%') AND c.category != 'Korean grocery store' THEN 1 ELSE 0 END) as is_korean\n  FROM establishments e\n  LEFT JOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\n  LEFT JOIN category c ON ec.category_id = c.category_id\n  WHERE c.category ILIKE '%thai%' \n     OR c.category ILIKE '%korean%'\n     OR e.name ILIKE '%thai%'\n     OR e.name ILIKE '%korean%'\n  GROUP BY e.gmap_id, e.name, e.avg_rating, e.num_of_reviews, e.slchd_establishment_key\n)\nSELECT \n  'Thai' as cuisine,\n  COUNT(*) as total_establishments,\n  AVG(avg_rating) as mean_rating,\n  MEDIAN(avg_rating) as median_rating,\n  SUM(num_of_reviews) as total_reviews,\n  AVG(num_of_reviews) as avg_reviews\nFROM base WHERE is_thai = 1\nUNION ALL\nSELECT \n  'Korean' as cuisine,\n  COUNT(*) as total_establishments,\n  AVG(avg_rating) as mean_rating,\n  MEDIAN(avg_rating) as median_rating,\n  SUM(num_of_reviews) as total_reviews,\n  AVG(num_of_reviews) as avg_reviews\nFROM base WHERE is_korean = 1;"})

