Action: run_sql({'query': "SELECT \n  ek.slchd_establishment_key,\n  ek.name,\n  ek.address,\n  ek.city,\n  COUNT(DISTINCT i.inspection_id) as inspection_count,\n  COUNT(v.violation_id) as violation_count,\n  SUM(CASE WHEN vc.critical THEN 1 ELSE 0 END) as critical_count\nFROM establishment_keys ek\nLEFT JOIN inspections i ON ek.slchd_establishment_key = i.slchd_establishment_key\nLEFT JOIN violations v ON i.inspection_id = v.inspection_id\nLEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\nWHERE ek.name ILIKE '%thai%' \n   OR ek.name ILIKE '%korean%' \n   OR ek.name ILIKE '%korea%'\n   OR ek.name ILIKE '%cupbop%'\n   OR ek.name ILIKE '%ombu%'\n   OR ek.name ILIKE '%seoul%'\n   OR ek.name ILIKE '%kimchi%'\n   OR ek.name ILIKE '%pho green papaya%'\n   OR ek.name ILIKE '%myung ga%'\n   OR ek.name ILIKE '%baang%'\n   OR ek.name ILIKE '%bangkok%'\n   OR ek.name ILIKE '%chabang%'\n   OR ek.name ILIKE '%sawadee%'\n   OR ek.name ILIKE '%tepui%'\n   OR ek.name ILIKE '%samron%'\n   OR ek.name ILIKE '%nuan%'\n   OR ek.name ILIKE '%tuk tuk%'\n   OR ek.name ILIKE '%chutney%'\n   OR ek.name ILIKE '%mano%'\n   OR ek.name ILIKE '%chaba%'\n   OR ek.name ILIKE '%k-recipe%'\n   OR ek.name ILIKE '%k recipe%'\nGROUP BY ek.slchd_establishment_key, ek.name, ek.address, ek.city;"})

