Action: run_sql({'query': "SELECT e.gmap_id, e.name, e.avg_rating, e.num_of_reviews, e.slchd_establishment_key, c.category\nFROM establishments e\nJOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\nJOIN category c ON ec.category_id = c.category_id\nWHERE c.category ILIKE '%thai%' OR c.category ILIKE '%korean%'\nORDER BY e.slchd_establishment_key NULLS LAST;"})

