Action: run_sql({'query': "SELECT e.gmap_id, e.name, e.address, e.slchd_establishment_key, e.avg_rating, c.category\nFROM establishments e\nJOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\nJOIN category c ON ec.category_id = c.category_id\nWHERE e.slchd_establishment_key IS NOT NULL\n  AND (c.category ILIKE '%thai%' OR c.category ILIKE '%korean%' OR e.name ILIKE '%thai%' OR e.name ILIKE '%korean%');"})

