Action: run_sql({'query': "SELECT \n  CASE \n    WHEN c.category ILIKE '%thai%' THEN 'Thai'\n    WHEN c.category ILIKE '%korean%' THEN 'Korean'\n  END AS cuisine,\n  ROUND(AVG(e.avg_rating), 2) AS avg_rating,\n  COUNT(DISTINCT e.gmap_id) AS restaurant_count\nFROM establishments e\nJOIN establishment_categories ec ON e.gmap_id = ec.gmap_id\nJOIN category c ON ec.category_id = c.category_id\nWHERE c.category ILIKE '%thai%' OR (c.category ILIKE '%korean%' AND c.category != 'Korean grocery store')\nGROUP BY cuisine;"})

Observation: {"row_count": 2, "truncated": false, "rows": [{"cuisine": "Thai", "avg_rating": 4.45, "restaurant_count": 116}, {"cuisine": "Korean", "avg_rating": 4.52, "restaurant_count": 47}]}

Action: run_sql({'query': "WITH cuisine_keys AS (\n  SELECT 'Thai' AS cuisine, 'ALLURE THAI DELISH|67 W 1700 S|SALT LAKE CITY' AS key UNION ALL\n  SELECT 'Thai', 'NUANS THAI KITCHEN|1871 E FORT UNION BLVD|COTTONWOOD HEIGHTS' UNION ALL\n  SELECT 'Thai', 'THAI ISSAN RESTAURANT|2644 W 4700 S|TAYLORSVILLE' UNION ALL\n  SELECT 'Korean', 'CUPBOP|2915 E 3300 S|MILLCREEK' UNION ALL\n  SELECT 'Korean', 'CUPBOP #G726HM|3269 E 5400 S|TAYLORSVILLE' UNION ALL\n  SELECT 'Korean', 'K RECIPE|3390 S STATE ST|SOUTH SALT LAKE'\n)\nSELECT \n  ck.cuisine,\n  COUNT(v.violation_id) AS total_violations,\n  SUM(CASE WHEN vc.critical THEN 1 ELSE 0 END) AS critical_violations,\n  SUM(CASE WHEN NOT vc.critical THEN 1 ELSE 0 END) AS non_critical_violations\nFROM cuisine_keys ck\nJOIN inspections i ON ck.key = i.slchd_establishment_key\nLEFT JOIN violations v ON i.inspection_id = v.inspection_id\nLEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\nGROUP BY ck.cuisine;"})

Observation: {"row_count": 2, "truncated": false, "rows": [{"cuisine": "Korean", "total_violations": 81, "critical_violations": 42.0, "non_critical_violations": 39.0}, {"cuisine": "Thai", "total_violations": 70, "critical_violations": 26.0, "non_critical_violations": 44.0}]}

Action: run_sql({'query': "WITH cuisine_keys AS (\n  SELECT \n    ek.slchd_establishment_key,\n    CASE \n      WHEN ek.name ILIKE '%thai%' THEN 'Thai'\n      WHEN ek.name ILIKE '%korean%' OR ek.name ILIKE '%cupbop%' OR ek.name ILIKE '%k recipe%' THEN 'Korean'\n    END AS cuisine\n  FROM establishment_keys ek\n  WHERE ek.name ILIKE '%thai%' OR ek.name ILIKE '%korean%' OR ek.name ILIKE '%cupbop%' OR ek.name ILIKE '%k recipe%'\n)\nSELECT \n  ck.cuisine,\n  COUNT(v.violation_id) AS total_violations,\n  SUM(CASE WHEN vc.critical THEN 1 ELSE 0 END) AS critical_violations,\n  SUM(CASE WHEN NOT vc.critical THEN 1 ELSE 0 END) AS non_critical_violations\nFROM cuisine_keys ck\nJOIN inspections i ON ck.slchd_establishment_key = i.slchd_establishment_key\nLEFT JOIN violations v ON i.inspection_id = v.inspection_id\nLEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\nGROUP BY ck.cuisine;"})

